  &reftitle.examples;

   Un ejemplo de Bootstrap


<?php
/**
 * Este fichero debe estar en APPLICATION_PATH . "/application/" (definido en
 * la configuración pasada a Yaf_Application), y llamarse Bootstrap.php, para
 * que Yaf_Application pueda encontrarlo.
 */
class Bootstrap extends Yaf_Bootstrap_Abstract {
    public function _initConfig(Yaf_Dispatcher $dispatcher) {
        echo "Primera llamada\n";
    }

    public function _initPlugin(Yaf_Dispatcher $dispatcher) {
        echo "Segunda llamada\n";
    }
}
?>




   Ejemplo de Yaf_Application::bootstrap


<?php

defined('APPLICATION_PATH') // APPLICATION_PATH será usada en el fichero ini de configuración
    || define('APPLICATION_PATH', __DIR__);

$application = new Yaf_Application(APPLICATION_PATH.'/conf/application.ini');
$application->bootstrap();
?>


